const addresses = (value) => {
  if (value && Array.isArray(value.value)) {
    return [...new Set(value.value.map((item) => String(item.address ?? '').trim().toLowerCase()).filter(Boolean))];
  }
  const raw = typeof value === 'string' ? value : '';
  return [...new Set((raw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) ?? []).map((email) => email.toLowerCase()))];
};
const output = [];
for (const item of $input.all()) {
  const value = item.json;
  const from = addresses(value.from ?? value.From)[0] ?? '';
  const to = addresses(value.to ?? value.To);
  if (!value.id || !value.threadId || !from || to.length === 0) continue;
  const sentAt = typeof value.date === 'string' && value.date
    ? new Date(value.date)
    : new Date(Number(value.internalDate));
  if (Number.isNaN(sentAt.getTime())) continue;
  output.push({ json: {
    gmailId: String(value.id),
    threadId: String(value.threadId),
    sentAt: sentAt.toISOString(),
    from,
    to,
    cc: addresses(value.cc ?? value.Cc),
    bcc: addresses(value.bcc ?? value.Bcc),
    subject: String(value.subject ?? value.Subject ?? 'Sin asunto').trim().slice(0, 200),
    ...(value.messageId ? { messageId: String(value.messageId).slice(0, 500) } : {}),
    text: String(value.text ?? value.snippet ?? '[Mensaje enviado desde Gmail]').slice(0, 20000),
  } });
}
return output;
